import fs from 'node:fs';
import path from 'node:path';
import { describe, expect, it } from 'vitest';
import { classifyQuestion, isChainQuestion } from '../src/search/route.js';

/**
 * The chain rule against real phrasing, not only the benchmark's (review of
 * 2026-11-16): ordinary two-clause questions about companies, people, markets
 * and products that must keep their route, beside every hop question of the
 * two reports packs, which must still reach the walk.
 *
 * tests/fixtures/route-pack-questions.json holds those packs' questions
 * (synthetic, generated by src/eval/packs): every deep-hop and nonlexical-hop
 * question of synthetic-reports-zh-x10 (184), every deep-hop question of
 * synthetic-reports-zh-v3-x10 (117), and up to four questions of each other
 * type of both.
 */

/** Ordinary questions with a second clause: a pronoun for what they name, a plural, a superlative, a comparison, a word fragment. */
const NOT_CHAINS: string[] = [
  // finance research, Chinese
  '贵州茅台2024年的营业收入是多少，它的毛利率比去年高吗？',
  '宁德时代的人均产值是多少，它在行业里排第几？',
  '比亚迪今年卖了多少辆车，它的海外销量占比多少？',
  '腾讯的人工智能业务进展如何，它和阿里比怎么样？',
  '招商银行的不良率是多少，它的拨备覆盖率呢？',
  '中国的人工智能公司有哪些，它们的估值一共多少？',
  '哪家公司今年营收最高，它的净利润是多少？',
  '港股今年涨得最好的板块是哪个，那个板块里的龙头是谁？',
  '特斯拉的人民币定价是多少，它在中国卖得好吗？',
  '华为去年研发投入多少，它的专利数量排全球第几？',
  '这份研报的结论是什么，它对新能源板块怎么看？',
  '美团的外卖业务和到店业务哪个利润更高，它们各占多少？',
  '隆基绿能的产能有多大，它和通威谁的成本更低？',
  '宁德时代和比亚迪谁的电池装机量更大？那家公司的市占率是多少？',
  '茅台和五粮液哪个市值更高，高多少？',
  '蔚来今年交付了多少辆车，他们的现金还能撑多久？',
  '有哪些券商发布了关于宁德时代的研报，它们的目标价是多少？',
  '我们的人员成本占比是多少，那个比例合理吗？',
  // people, companies and products, Chinese
  '给我讲一个关于茅台的故事，它最近股价怎么样？',
  '马斯克现在管理哪些公司，他在每家公司的持股比例是多少？',
  '李彦宏是哪一年创办百度的，他之前在哪里工作？',
  '小米汽车SU7的续航是多少，那个版本最便宜？',
  '苹果发布了一款新手机，它的售价是多少？',
  '阿里巴巴的人事变动有哪些，它们对股价有影响吗？',
  '小红书上市了吗？它的估值是多少？',
  '宁德时代的那个新电池叫什么，它的能量密度是多少？',
  '比亚迪和特斯拉今年谁卖得更多，差距有多大？',
  '张一鸣卸任后在做什么，他还持有字节的股份吗？',
  // English
  'What was Apple\'s revenue in 2024, and how did it compare to 2023?',
  'List all incidents in 2025. Who fixed them?',
  'Which companies did Berkshire buy last year, and what did they pay?',
  'Tesla cut prices in China; how did its margins react?',
  'Who are the largest shareholders of Nvidia, and how much do they own?',
  'Tell me a story about Warren Buffett. What is he doing now?',
  'Microsoft acquired Activision. When did the deal close, and what did it cost?',
  'How many employees does Amazon have, and what is their average salary?',
  'What is the iPhone 16\'s battery life? Is it better than the Pixel\'s?',
  'Jensen Huang founded Nvidia in 1993. What else has he built?',
  'Which product sold the most units last quarter, and what was its margin?',
  'Which bank has the highest deposit rate? Is that bank safe?',
  'Name the top five EV makers by sales. How did they do in Europe?',
  'What do analysts expect for Meta\'s earnings, and when will it report?',
  'Compare Visa and Mastercard: which one grew faster, and by how much?',
  'Satya Nadella became CEO in 2014. What has he changed since then?',
  'What are Samsung\'s main products, and which of them is most profitable?',
  'Netflix raised prices again. Did it lose subscribers?',
  'How much did OpenAI raise, and who led the round?',
  'Which supplier was cheaper, Foxconn or Pegatron, and why did that supplier win?',
  '平台组今年排第一名的工程师是谁，他修了几起事故？',
];

/** Real phrasing that does chain: the later clause asks about what the first part has to find. */
const CHAINS: string[] = [
  '这家公司的创始人是谁，他毕业于哪所大学？',
  '收购了Figma的那家公司是谁，它的CEO是谁？',
  '谁是宁德时代的第一大客户？那家客户今年的订单量有多少？',
  '去年负责这个项目的人是谁？此人现在在哪个部门？',
  // 一位 / 一名 / 一家 introduce a person or an organisation whatever the noun (the life fixture's c-chain)
  '周敏介绍给林晓认识的跑步教练推荐了一位理疗师，这位理疗师在哪家机构坐诊？',
  '朋友给我介绍了一家律所，那家律所的合伙人是谁？',
  'An analyst at Morgan Stanley downgraded Nvidia. Which fund does that analyst cover?',
  'Who is Apple\'s chief executive? What did he say about AI last quarter?',
  'Who signed the supply deal with Foxconn? Which division does that person run?',
];

describe('the chain rule on real phrasing', () => {
  it(`keeps ${NOT_CHAINS.length} ordinary two-clause questions off the walk`, () => {
    expect(NOT_CHAINS.length).toBeGreaterThanOrEqual(40);
    const walked = NOT_CHAINS.filter((q) => isChainQuestion(q) || classifyQuestion(q).by === 'rule:chain');
    expect(walked).toEqual([]);
  });

  it('keeps the count or list route of those that have one', () => {
    const expected: [string, string][] = [
      ['中国的人工智能公司有哪些，它们的估值一共多少？', 'aggregate'],
      ['哪家公司今年营收最高，它的净利润是多少？', 'aggregate'],
      ['港股今年涨得最好的板块是哪个，那个板块里的龙头是谁？', 'aggregate'],
      ['有哪些券商发布了关于宁德时代的研报，它们的目标价是多少？', 'aggregate'],
      ['List all incidents in 2025. Who fixed them?', 'list'],
      ['Which bank has the highest deposit rate? Is that bank safe?', 'aggregate'],
      ['Which companies did Berkshire buy last year, and what did they pay?', 'list'],
    ];
    for (const [q, kind] of expected) expect(classifyQuestion(q).kind, q).toBe(kind);
  });

  it.each(CHAINS)('walks %s', (q) => {
    expect(classifyQuestion(q)).toMatchObject({ kind: 'multihop', by: 'rule:chain' });
  });
});

describe('the chain rule on the reports packs', () => {
  const fixture = JSON.parse(fs.readFileSync(path.join(__dirname, 'fixtures/route-pack-questions.json'), 'utf8')) as {
    chains: Record<string, string[]>;
    notChains: Record<string, string[]>;
  };

  it.each(Object.keys(fixture.chains))('walks every hop question of %s', (pack) => {
    const questions = fixture.chains[pack];
    expect(questions.length).toBeGreaterThan(100);
    const missed = questions.filter((q) => classifyQuestion(q).by !== 'rule:chain');
    expect(missed).toEqual([]);
  });

  it.each(Object.keys(fixture.notChains))('walks none of the other questions of %s', (pack) => {
    const walked = fixture.notChains[pack].filter((q) => classifyQuestion(q).by === 'rule:chain');
    expect(walked).toEqual([]);
  });
});
